    uint8_t _qp_next_u_reg_u_reg_if_error_q = s->u_reg_u_reg_if_error_q;
    uint8_t _qp_next_u_reg_u_intr_state_fmt_threshold_q = s->u_reg_u_intr_state_fmt_threshold_q;
